package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

class DefaultParserParseTest {

    /**
     * A test subclass that intercepts the overload parse(Options, String[], Properties, boolean)
     * so we can assert that the simple parse(Options, String[], boolean) delegates to it.
     */
    private static class TestParser extends DefaultParser {
        boolean invoked;
        Options receivedOptions;
        String[] receivedArguments;
        Properties receivedProperties;
        Boolean receivedStopAtNonOption;
        CommandLine returnValue;
        ParseException toThrow;

        TestParser(CommandLine returnValue) {
            this.returnValue = returnValue;
        }

        TestParser() {
            this.returnValue = null;
        }

        @Override
        public CommandLine parse(final Options options, final String[] arguments, final Properties properties, final boolean stopAtNonOption)
                throws ParseException {
            invoked = true;
            receivedOptions = options;
            receivedArguments = arguments;
            receivedProperties = properties;
            receivedStopAtNonOption = stopAtNonOption;
            if (toThrow != null) {
                throw toThrow;
            }
            return returnValue;
        }
    }

    @Test
    void testParseDelegatesToOverload_stopAtNonOptionFalse() throws Exception {
        // prepare
        Options opts = new Options();
        String[] args = new String[] { "a", "b" };

        // create a CommandLine instance reflectively to be safe if constructor visibility varies
        CommandLine sentinel = createCommandLineInstance();

        TestParser p = new TestParser(sentinel);

        // act
        CommandLine result = p.parse(opts, args, false);

        // assert delegation happened and parameters preserved
        assertTrue(p.invoked, "Expected overloaded parse to be invoked");
        assertSame(opts, p.receivedOptions, "Options should be forwarded");
        assertArrayEquals(args, p.receivedArguments, "Arguments should be forwarded");
        assertNull(p.receivedProperties, "Properties parameter should be null per delegation");
        assertEquals(Boolean.FALSE, p.receivedStopAtNonOption, "stopAtNonOption should be forwarded (false)");
        assertSame(sentinel, result, "Return value should come from delegated method");
    }

    @Test
    void testParseDelegatesToOverload_stopAtNonOptionTrue_throwsParseException() {
        Options opts = new Options();
        String[] args = new String[] { "x" };

        TestParser p = new TestParser();
        p.toThrow = new ParseException("forced");

        // assert that exception from delegated method is propagated
        ParseException ex = assertThrows(ParseException.class, () -> p.parse(opts, args, true));
        assertEquals("forced", ex.getMessage());
        assertTrue(p.invoked, "Expected overloaded parse to be invoked even when it throws");
        assertEquals(Boolean.TRUE, p.receivedStopAtNonOption, "stopAtNonOption should be forwarded (true)");
    }

    @Test
    void testPrivateConstructorViaReflection_and_fieldValues() throws Exception {
        // create a Consumer<Option> that toggles a flag to ensure it is stored and retrievable
        AtomicBoolean consumerCalled = new AtomicBoolean(false);
        Consumer<Option> cust = o -> consumerCalled.set(true);

        // obtain private constructor (boolean, Boolean, Consumer<Option>) and invoke it
        Constructor<DefaultParser> ctor = DefaultParser.class.getDeclaredConstructor(boolean.class, Boolean.class, Consumer.class);
        ctor.setAccessible(true);

        DefaultParser instance = ctor.newInstance(false, Boolean.TRUE, cust);
        assertNotNull(instance, "Instance should be created via private constructor");

        // read private / final fields via reflection and assert values
        Field allowPartialMatchingField = DefaultParser.class.getDeclaredField("allowPartialMatching");
        Field stripField = DefaultParser.class.getDeclaredField("stripLeadingAndTrailingQuotes");
        Field deprecatedHandlerField = DefaultParser.class.getDeclaredField("deprecatedHandler");

        allowPartialMatchingField.setAccessible(true);
        stripField.setAccessible(true);
        deprecatedHandlerField.setAccessible(true);

        boolean allowPartialMatching = allowPartialMatchingField.getBoolean(instance);
        Boolean strip = (Boolean) stripField.get(instance);
        @SuppressWarnings("unchecked")
        Consumer<Option> retrievedConsumer = (Consumer<Option>) deprecatedHandlerField.get(instance);

        assertFalse(allowPartialMatching, "allowPartialMatching should be the value passed to constructor (false)");
        assertEquals(Boolean.TRUE, strip, "stripLeadingAndTrailingQuotes should match the passed Boolean.TRUE");
        assertSame(cust, retrievedConsumer, "deprecatedHandler should be the same instance provided");

        // also exercise calling the consumer via retrieved reference to ensure it's the same behavior
        retrievedConsumer.accept(null); // should not throw
        assertTrue(consumerCalled.get(), "Consumer provided to private ctor should be stored and invokable");
    }

    // helper to construct a CommandLine instance reflectively (handles different visibilities)
    private static CommandLine createCommandLineInstance() throws NoSuchMethodException, IllegalAccessException, InvocationTargetException, InstantiationException {
        Constructor<CommandLine> c = CommandLine.class.getDeclaredConstructor();
        c.setAccessible(true);
        return c.newInstance();
    }
}

